    display: flex;
    align-items: center;
    height: calc(2em - 2px);
    background-image: linear-gradient(90deg, rgba(255,255,255,0.5) 0%, white 100%);
}

div.colorbutton-picker-alpha input[type=range] {
    width: 100%;
}

div.colorbutton-picker-spectrum {
    display: flex;
    height: 150px;
    margin: 0 0.25em;
}

