    height: 100%;
}

div.height-profile-loading-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    padding-left: 0.5em;
    padding-bottom: 0.5em;
    height: 100%;
}

div.height-profile-loading-indicator > div.spinner {
    width: 1.5em;
    height: 1.5em;
    margin-right: 0.25em;
}

div.height-profile-error {
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: red;
}

.height-profile-dataset-select {
    display: flex;
    flex-wrap: wrap;
    gap: 0.6rem;
    position: absolute;
    right: 0;
    bottom: 0;
}

.height-profile-dataset-select > div {
    display: flex;
    align-items: center;
    gap: 0.2rem;
}
