    position: absolute;
    left: 0;
    right: 0;
    top: 0;
    bottom: 0;
}

div.obliqueview-empty-overlay {
    position: absolute;
    left: 0;
    right: 0;
    top: 0;
    bottom: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: rgba(200, 200, 200);
    z-index: 4;
}

div.obliqueview-map {
    height: 100%;
}

div.obliqueview-nav-rotate {
    position: absolute;
    right: 1em;
    top: 1em;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;
    width: 6em;
    height: 6em;
    margin-bottom: 0.5em;
    transition: transform 0.5s;
}

div.obliqueview-nav-rotate > span {
    flex: 0 0 2em;
}

div.obliqueview-nav-circle {
    position: absolute;
    left: .75em;
    top: .75em;
    right: .75em;
    bottom: .75em;
    border: 4px solid var(--map-button-bg-color);
    z-index: -1;
    border-radius: 4.5em;
}

span.obliqueview-nav-dir {
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    cursor: pointer;
    transition: transform 0.5s;
    border-radius: 6px;
    color: var(--map-button-text-color);
    background-color: var(--map-button-bg-color);
    box-shadow: 0px 5px 10px rgba(136, 136, 136, 0.5);
    line-height: 2em;
}

div.obliqueview-nav-zoom {
    position: absolute;
    right: 1.5em;
    top: 8em;
    width: 2em;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--map-button-text-color);
    background-color: var(--map-button-bg-color);
    box-shadow: 0px 5px 10px rgba(136, 136, 136, 0.5);
    border-radius: 4px;
    cursor: pointer;
    transition: background-color 0.5s, color 0.5s;
    flex-direction: column;
    margin: 0 1.5em 0.5em 1em;
}

div.obliqueview-nav-zoom > span {
    height: 2em;
    width: 1.5em;
    display: flex;
    align-items: center;
    justify-content: center;
}

div.obliqueview-nav-zoom > span:first-child {
    border-bottom: 1px solid var(--map-button-text-color);
}

