    backdrop-filter: blur(3px);
    font-size: 75%;
    display: flex;
    align-items: center;
}

span.obliqueview-bottombar-spacer {
    flex: 1 1 auto;
}

div.obliqueview-scalechooser {
    width: 10em;
    display: flex;
    align-items: center;
}

div.obliqueview-scalechooser > div.input-container {
    flex: 1 1 auto;
